// ===========================================================================
// Фикстура tests/agent/ui_off_test.py: документ с двумя кнопками.
//
// Слушатели ставит сам тест через $.ui.doc(...).on — фикстура только
// открывает документ, чтобы журнал и счётчики не смешивались с подписками
// самой игры.
// ===========================================================================

$.ready(() => {
    $.gfx.color('#101820');
    const doc = $.ui.doc('ui/off.rml').show();
    $.store.set('uioff_doc', doc.id);
});
